(4702355, 677484, 53147, '<td valign="top">Such a cool and freaky looking flower. Nice colors and it works pretty well soft, but at the same time I crave to see the head super sharp as it blends into the bokeh background. That of course wouldnt score as well so I do believe you made the right choice. ;)</td>', 'Such a cool and freaky looking flower. Nice colors and it works pretty well soft, but at the same time I crave to see the head super sharp as it blends into the bokeh background. That of course wouldnt score as well so I do believe you made the right choice. ;)', '2008-05-14 16:45:29.000000', NULL, 1),
(4702356, 678509, 53147, '<td valign="top">Lovely shot. The soft focus works great on horses and even better with the carpet of flowers. Strong image.</td>', 'Lovely shot. The soft focus works great on horses and even better with the carpet of flowers. Strong image.', '2008-05-14 16:45:31.000000', NULL, 1),
(4702357, 678507, 53147, '<td valign="top">Interesting and intriguing image. The dark feel and blue tones work well.</td>', 'Interesting and intriguing image. The dark feel and blue tones work well.', '2008-05-14 16:46:20.000000', NULL, 1),
(4702358, 678361, 53147, '<td valign="top">Lovely image. Sharp and soft all at the same time. It works well. Bumping up.</td>', 'Lovely image. Sharp and soft all at the same time. It works well. Bumping up.', '2008-05-14 16:47:10.000000', NULL, 1),
(4702376, 678366, 811, '<td valign="top">This looks so much like my husband when he was a little boy... . amazingly so, even.  :)</td>', 'This looks so much like my husband when he was a little boy... . amazingly so, even.  :)', '2008-05-14 17:02:39.000000', NULL, 1),
