(4702471, 678610, 811, '<td valign="top">When I saw the thumbnail, I was thinking a picture of a dagger wouldn''t look "right" using soft focus.<br/> <br/> <br/>I was wrong.  Nicely done.</td>', 'When I saw the thumbnail, I was thinking a picture of a dagger wouldn''t look "right" using soft focus.  I was wrong.  Nicely done.', '2008-05-14 17:45:21.000000', NULL, 1),
(4702473, 678412, 811, '<td valign="top">It almost looks like fire</td>', 'It almost looks like fire', '2008-05-14 17:46:53.000000', NULL, 1),
(4702481, 678422, 90387, '<td valign="top">Unusual topic, strange composition, odd colors.  Definitely one of my top pix for the challenge.  Very out of the box!</td>', 'Unusual topic, strange composition, odd colors.  Definitely one of my top pix for the challenge.  Very out of the box!', '2008-05-14 17:52:07.000000', NULL, 1),
(4702483, 678599, 41142, '<td valign="top">More out of focus than soft focus...</td>', 'More out of focus than soft focus...', '2008-05-14 17:53:49.000000', NULL, 1),
(4702485, 677967, 41142, '<td valign="top">Seems pretty sharp. But still pretty.</td>', 'Seems pretty sharp. But still pretty.', '2008-05-14 17:54:13.000000', NULL, 1),
(4702486, 677993, 90387, '<td valign="top">This certainly stands out amongst the majority of other images in the challenge.  It''s a great subject!  I like to contrast between a rather gritty image, with soft focus.  Hope to see this on the front page.</td>', 'This certainly stands out amongst the majority of other images in the challenge.  It''s a great subject!  I like to contrast between a rather gritty image, with soft focus.  Hope to see this on the front page.', '2008-05-14 17:55:09.000000', NULL, 1),
(4702489, 677366, 49804, '<td valign="top">Really incredible shot, nice work with lighting and everything, my only problem is the lack of "soft focus", there is great bokeh, but the main subject is completely in focus.</td>', 'Really incredible shot, nice work with lighting and everything, my only problem is the lack of "soft focus", there is great bokeh, but the main subject is completely in focus.', '2008-05-14 17:55:58.000000', NULL, 1),
