(4706979, 677935, 92383, '<td valign="top">Weird, Soft but with harsh color and stark contrast.</td>', 'Weird, Soft but with harsh color and stark contrast.', '2008-05-16 15:53:20.000000', NULL, 1),
(4706981, 678092, 92383, '<td valign="top">This looks like a frame from an <a href="//en.wikipedia.org/wiki/Exploitation_film" rel="nofollow" target="_blank">exploitation</a> film.  I imagine the Title, "Night of the Beaver" or the video to Primus'' "Wynnona''s big brown beaver".</td>', 'This looks like a frame from an exploitation film.  I imagine the Title, "Night of the Beaver" or the video to Primus'' "Wynnona''s big brown beaver".', '2008-05-16 16:00:08.000000', NULL, 1),
(4706982, 678366, 92383, '<td valign="top">Looks really crisp to me.</td>', 'Looks really crisp to me.', '2008-05-16 16:01:53.000000', NULL, 1),
(4706985, 678424, 92383, '<td valign="top">Just to far past soft for me.</td>', 'Just to far past soft for me.', '2008-05-16 16:02:40.000000', NULL, 1),
(4706987, 677502, 92383, '<td valign="top">What the hell? This is very strange looking.  Is this that noodling thing I saw?  hmm, I don''t know what to do with this one.  it almost looks like an effect filter.</td>', 'What the hell? This is very strange looking.  Is this that noodling thing I saw?  hmm, I don''t know what to do with this one.  it almost looks like an effect filter.', '2008-05-16 16:05:04.000000', NULL, 1),
(4706988, 678316, 92383, '<td valign="top">Saw a beaver this belongs with to me.  Like a frame from a horror exploitation film.</td>', 'Saw a beaver this belongs with to me.  Like a frame from a horror exploitation film.', '2008-05-16 16:06:13.000000', NULL, 1),
(4706991, 677389, 92383, '<td valign="top">Looks like dew or fog.</td>', 'Looks like dew or fog.', '2008-05-16 16:07:44.000000', NULL, 1),
(4706993, 677472, 92383, '<td valign="top">looks like blurry fisheye to me.</td>', 'looks like blurry fisheye to me.', '2008-05-16 16:10:10.000000', NULL, 1),
(4706997, 678035, 92383, '<td valign="top">Looks very crisp?</td>', 'Looks very crisp?', '2008-05-16 16:11:07.000000', NULL, 1),
(4707001, 677878, 92383, '<td valign="top">Very spooky and dark.  I like it, but I bet many here will say it is too dark.</td>', 'Very spooky and dark.  I like it, but I bet many here will say it is too dark.', '2008-05-16 16:13:02.000000', NULL, 1),
(4707007, 677366, 74209, '<td valign="top">Apocalyptic.  Intense.</td>', 'Apocalyptic.  Intense.', '2008-05-16 16:16:25.000000', NULL, 1),
(4707008, 678488, 92383, '<td valign="top">Best 10</td>', 'Best 10', '2008-05-16 16:18:13.000000', NULL, 1),
(4707020, 678258, 93001, '<td valign="top">This is a beautiful photograph.  Unlike many of the other entries in this challenge, with yours, the soft focus really makes the picture work, it adds to the story it''s telling.  I love the glow of light around her as well.</td>', 'This is a beautiful photograph.  Unlike many of the other entries in this challenge, with yours, the soft focus really makes the picture work, it adds to the story it''s telling.  I love the glow of light around her as well.', '2008-05-16 16:24:58.000000', NULL, 1),
(4707027, 678555, 93001, '<td valign="top">I''ve been frustrated by the macros in this challenge that haven''t really tackled the concept of soft focus beyond having a soft background.  Yours is different!  The bright glow and dark background make the softness of the focus on the main subject really work for me in this picture.  I love the ethereal look to the flowers.</td>', 'I''ve been frustrated by the macros in this challenge that haven''t really tackled the concept of soft focus beyond having a soft background.  Yours is different!  The bright glow and dark background make the softness of the focus on the main subject really work for me in this picture.  I love the ethereal look to the flowers.', '2008-05-16 16:27:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4707032, 677133, 93001, '<td valign="top">It''s a very simple concept, but it works quite well for this challenge.  The red lights add some life without distracting from the drops.  I think it would have more energy if you had captured the street at an angle, crossing the photo instead of heading straight up it.</td>', 'It''s a very simple concept, but it works quite well for this challenge.  The red lights add some life without distracting from the drops.  I think it would have more energy if you had captured the street at an angle, crossing the photo instead of heading straight up it.', '2008-05-16 16:30:01.000000', NULL, 1),
(4707034, 677366, 92383, '<td valign="top">This sucks cause it is not soft at all yet it is clearly a great picture.  It is so obvious to me that you have the ability to dial in the exact amount of softness... makes me wonder if I know what the heck I am doing.</td>', 'This sucks cause it is not soft at all yet it is clearly a great picture.  It is so obvious to me that you have the ability to dial in the exact amount of softness... makes me wonder if I know what the heck I am doing.', '2008-05-16 16:30:33.000000', NULL, 1),
(4707035, 678249, 92383, '<td valign="top">One of my favorites. 9</td>', 'One of my favorites. 9', '2008-05-16 16:31:40.000000', NULL, 1),
(4707037, 678394, 92383, '<td valign="top">Nice pic for a wall</td>', 'Nice pic for a wall', '2008-05-16 16:32:13.000000', NULL, 1),
(4707042, 677444, 92383, '<td valign="top">I keep seeing the Disney "D".  Just thought I would let you know.. :)</td>', 'I keep seeing the Disney "D".  Just thought I would let you know.. :)', '2008-05-16 16:37:48.000000', NULL, 1),
(4707048, 676998, 93001, '<td valign="top">Amazing lines throughout the image.  I find it to be a complex and interesting photo, and I understand the choice to have the model wearing so little - it really emphasizes the intimacy of the moment.  However, the model''s plain white undergarments distract from the overall feel.  If her clothing was more fitting to the setting - tropical, soft, romantic - it would have worked better for me.</td>', 'Amazing lines throughout the image.  I find it to be a complex and interesting photo, and I understand the choice to have the model wearing so little - it really emphasizes the intimacy of the moment.  However, the model''s plain white undergarments distract from the overall feel.  If her clothing was more fitting to the setting - tropical, soft, romantic - it would have worked better for me.', '2008-05-16 16:40:36.000000', NULL, 1),
(4707054, 678483, 91314, '<td valign="top">Out of focus</td>', 'Out of focus', '2008-05-16 16:44:54.000000', NULL, 1),
(4707056, 677944, 91314, '<td valign="top">Out of focus</td>', 'Out of focus', '2008-05-16 16:48:29.000000', NULL, 1),
(4707057, 677450, 91314, '<td valign="top">Out of focus</td>', 'Out of focus', '2008-05-16 16:48:40.000000', NULL, 1),
(4707295, 678566, 93001, '<td valign="top">The background is like a painting - beautifully done!</td>', 'The background is like a painting - beautifully done!', '2008-05-16 19:47:47.000000', NULL, 1),
(4707414, 678451, 91089, '<td valign="top">This photo is great. I really like it. I just don''t like the purple/blue border</td>', 'This photo is great. I really like it. I just don''t like the purple/blue border', '2008-05-16 20:23:14.000000', NULL, 1),
(4707418, 677167, 91089, '<td valign="top">This fits better in the Triangular challenge.</td>', 'This fits better in the Triangular challenge.', '2008-05-16 20:24:17.000000', NULL, 1),
(4707456, 678625, 76335, '<td valign="top">Nicely soft but overexposed in places. Great capture of emotion.</td>', 'Nicely soft but overexposed in places. Great capture of emotion.', '2008-05-16 21:20:43.000000', NULL, 1),
(4707464, 677718, 76335, '<td valign="top">Brave use of DOF to achieve softness. Probably won''t do well, which is too bad -- it''s very creative!</td>', 'Brave use of DOF to achieve softness. Probably won''t do well, which is too bad -- it''s very creative!', '2008-05-16 21:32:43.000000', NULL, 1),
(4707466, 678426, 76335, '<td valign="top">Nice! The light on her nose distracts from the overall softness, but still a nice capture.</td>', 'Nice! The light on her nose distracts from the overall softness, but still a nice capture.', '2008-05-16 21:33:43.000000', NULL, 1),
(4707469, 677414, 76335, '<td valign="top">Great capture, but I''m not sure that softness adds anything.</td>', 'Great capture, but I''m not sure that softness adds anything.', '2008-05-16 21:34:54.000000', NULL, 1),
(4707470, 678654, 76335, '<td valign="top">Great title and beautifully soft. I''m not sure I see the rain very clearly, but the pose and emotion are perfect.</td>', 'Great title and beautifully soft. I''m not sure I see the rain very clearly, but the pose and emotion are perfect.', '2008-05-16 21:36:17.000000', NULL, 1),
(4707471, 678530, 76335, '<td valign="top">One of the better flower shots in this challenge (and there are lots!). The softness works and doesn''t take away from the drama of your vantage point.</td>', 'One of the better flower shots in this challenge (and there are lots!). The softness works and doesn''t take away from the drama of your vantage point.', '2008-05-16 21:37:07.000000', NULL, 1),
(4707473, 678629, 76335, '<td valign="top">Great angle and tones. Soft but not at the expense of your subject''s subtle details.</td>', 'Great angle and tones. Soft but not at the expense of your subject''s subtle details.', '2008-05-16 21:37:55.000000', NULL, 1),
(4707476, 677648, 76335, '<td valign="top">Tones are a little dull -- more contrast is needed. Nicely compsoed though and the DOF is clever.</td>', 'Tones are a little dull -- more contrast is needed. Nicely compsoed though and the DOF is clever.', '2008-05-16 21:39:30.000000', NULL, 1),
(4707477, 678342, 76335, '<td valign="top">The stray hair is a bit distracting, but this is nicely composed, and soft without the loss of details.</td>', 'The stray hair is a bit distracting, but this is nicely composed, and soft without the loss of details.', '2008-05-16 21:40:28.000000', NULL, 1),
(4707478, 678611, 76335, '<td valign="top">Great portrait, excellent lighting and effectively soft.</td>', 'Great portrait, excellent lighting and effectively soft.', '2008-05-16 21:40:58.000000', NULL, 1),
(4707479, 677795, 76335, '<td valign="top">Brave use of negative space. Nicely done.</td>', 'Brave use of negative space. Nicely done.', '2008-05-16 21:41:17.000000', NULL, 1),
(4707484, 678035, 76335, '<td valign="top">Beautiful capture but not very soft.</td>', 'Beautiful capture but not very soft.', '2008-05-16 21:48:39.000000', NULL, 1),
(4707486, 677638, 76335, '<td valign="top">More out of focus than soft. Great expression captured though.</td>', 'More out of focus than soft. Great expression captured though.', '2008-05-16 21:49:05.000000', NULL, 1),
(4707487, 677654, 76335, '<td valign="top">Is that a finger in front of the lens to the left?</td>', 'Is that a finger in front of the lens to the left?', '2008-05-16 21:49:48.000000', NULL, 1),
(4707488, 678504, 76335, '<td valign="top">I love the yellows and greens here.</td>', 'I love the yellows and greens here.', '2008-05-16 21:50:15.000000', NULL, 1),
(4707490, 678288, 76335, '<td valign="top">Certainly one of the more original entries here. Might be a little too soft.</td>', 'Certainly one of the more original entries here. Might be a little too soft.', '2008-05-16 21:50:59.000000', NULL, 1),
(4707491, 678474, 76335, '<td valign="top">Not at all soft. Interesting processing though.</td>', 'Not at all soft. Interesting processing though.', '2008-05-16 21:51:14.000000', NULL, 1),
(4707492, 678171, 76335, '<td valign="top">Excellent lighting. Curious to hear how you achieved this effect.</td>', 'Excellent lighting. Curious to hear how you achieved this effect.', '2008-05-16 21:51:55.000000', NULL, 1),
(4707493, 678152, 76335, '<td valign="top">Nice tones. Soft and abstract to good effect.</td>', 'Nice tones. Soft and abstract to good effect.', '2008-05-16 21:52:41.000000', NULL, 1),
(4707495, 676963, 76335, '<td valign="top">Great pose, nice softness.</td>', 'Great pose, nice softness.', '2008-05-16 21:53:12.000000', NULL, 1),
(4707496, 678615, 76335, '<td valign="top">Great lighting and unique POV. Too sharp in areas though.</td>', 'Great lighting and unique POV. Too sharp in areas though.', '2008-05-16 21:54:09.000000', NULL, 1),
(4707497, 678412, 76335, '<td valign="top">Dramatic lighting and beautiful red tones.</td>', 'Dramatic lighting and beautiful red tones.', '2008-05-16 21:54:28.000000', NULL, 1),
(4707501, 678538, 76335, '<td valign="top">Excellent. The border is a bit much though.</td>', 'Excellent. The border is a bit much though.', '2008-05-16 21:56:18.000000', NULL, 1),
(4707507, 678572, 76335, '<td valign="top">Great capture but not very soft.</td>', 'Great capture but not very soft.', '2008-05-16 21:58:48.000000', NULL, 1),
(4707510, 677047, 76335, '<td valign="top">Original and expertly processed. The BW is beautiful and the lighting is just right.</td>', 'Original and expertly processed. The BW is beautiful and the lighting is just right.', '2008-05-16 21:59:48.000000', NULL, 1),
(4707511, 678529, 76335, '<td valign="top">Beautiful nature shot, but it doesn''t strike me as particularly soft.</td>', 'Beautiful nature shot, but it doesn''t strike me as particularly soft.', '2008-05-16 22:00:14.000000', NULL, 1),
(4707516, 678258, 76335, '<td valign="top">Beautifully framed. Dreamy indeed.</td>', 'Beautifully framed. Dreamy indeed.', '2008-05-16 22:01:46.000000', NULL, 1),
(4707521, 678365, 76335, '<td valign="top">I <i>want</i> to like this -- really, I do. The shadows give him an evil look at first glance. And the skin doesn''t look very natural for some reason. An excellent attempt though. I like how you framed it.</td>', 'I want to like this -- really, I do. The shadows give him an evil look at first glance. And the skin doesn''t look very natural for some reason. An excellent attempt though. I like how you framed it.', '2008-05-16 22:03:52.000000', NULL, 1),
(4707525, 678226, 76335, '<td valign="top">More OOF than soft. Priceless expression though.</td>', 'More OOF than soft. Priceless expression though.', '2008-05-16 22:05:27.000000', NULL, 1),
(4707526, 678424, 76335, '<td valign="top">Softness should never be at the expense of definition. This is blurry and hard to read. Keep trying!</td>', 'Softness should never be at the expense of definition. This is blurry and hard to read. Keep trying!', '2008-05-16 22:06:33.000000', NULL, 1),
(4707531, 677385, 76335, '<td valign="top">Interesting but hardly soft and subtle.</td>', 'Interesting but hardly soft and subtle.', '2008-05-16 22:07:48.000000', NULL, 1),
(4707534, 678400, 76335, '<td valign="top">Naturally! Nice colors.</td>', 'Naturally! Nice colors.', '2008-05-16 22:08:20.000000', NULL, 1),
(4707535, 677664, 4793, '<td valign="top">Beautiful</td>', 'Beautiful', '2008-05-16 22:08:21.000000', NULL, 1),
(4707537, 678509, 76335, '<td valign="top">Nicely composed, but it looks surreal.</td>', 'Nicely composed, but it looks surreal.', '2008-05-16 22:08:50.000000', NULL, 1),
(4707539, 677828, 76335, '<td valign="top">Excellent lighting and softness.</td>', 'Excellent lighting and softness.', '2008-05-16 22:09:18.000000', NULL, 1),
(4707541, 678639, 76335, '<td valign="top">Edgy and original, but somewhat hard to "read."</td>', 'Edgy and original, but somewhat hard to "read."', '2008-05-16 22:10:07.000000', NULL, 1),
(4707543, 677167, 76335, '<td valign="top">I think your challenge left without you.</td>', 'I think your challenge left without you.', '2008-05-16 22:10:41.000000', NULL, 1),
(4707549, 678158, 76335, '<td valign="top">Beautiful capture of genuine emotion. The things on the curtain are somewhat distracting, and the processing is a bit too squeaky clean, especially for this challenge (for me, at least). The lighting and focus is almost perfect.</td>', 'Beautiful capture of genuine emotion. The things on the curtain are somewhat distracting, and the processing is a bit too squeaky clean, especially for this challenge (for me, at least). The lighting and focus is almost perfect.', '2008-05-16 22:13:48.000000', NULL, 1),
(4707554, 678164, 76335, '<td valign="top">More psychadelic than delicate. Effective use of lighting though.</td>', 'More psychadelic than delicate. Effective use of lighting though.', '2008-05-16 22:15:09.000000', NULL, 1),
(4707560, 678567, 76335, '<td valign="top">Dandelions are popular here. Challenge aside, I like this the best so far -- expertly composed and somewhat abstract. It''s not really soft though.</td>', 'Dandelions are popular here. Challenge aside, I like this the best so far -- expertly composed and somewhat abstract. It''s not really soft though.', '2008-05-16 22:17:06.000000', NULL, 1),
(4707564, 677993, 76335, '<td valign="top">Original and interesting. I don''t care for the processing though -- it''s hard on the eyes and doesn''t really add anything to the image.</td>', 'Original and interesting. I don''t care for the processing though -- it''s hard on the eyes and doesn''t really add anything to the image.', '2008-05-16 22:18:41.000000', NULL, 1),
(4707567, 678246, 76335, '<td valign="top">WAY oversaturated, overexposed in places, and not really soft.</td>', 'WAY oversaturated, overexposed in places, and not really soft.', '2008-05-16 22:19:43.000000', NULL, 1),
(4707568, 678379, 76335, '<td valign="top">Original still life. More OOF than soft.</td>', 'Original still life. More OOF than soft.', '2008-05-16 22:20:12.000000', NULL, 1),
(4707577, 678487, 76335, '<td valign="top">Soft, but no real focal point and not very interesting.</td>', 'Soft, but no real focal point and not very interesting.', '2008-05-16 22:23:04.000000', NULL, 1),
(4707582, 677994, 76335, '<td valign="top">Excellent capture and beautifully processed.</td>', 'Excellent capture and beautifully processed.', '2008-05-16 22:25:28.000000', NULL, 1),
(4707584, 678451, 76335, '<td valign="top">More dandelions... This one''s interesting. Nice softness and tones.</td>', 'More dandelions... This one''s interesting. Nice softness and tones.', '2008-05-16 22:26:20.000000', NULL, 1),
(4707586, 678620, 76335, '<td valign="top">Stunning. Great exposure and colors.</td>', 'Stunning. Great exposure and colors.', '2008-05-16 22:26:51.000000', NULL, 1),
(4707588, 677736, 76335, '<td valign="top">Nice high key portrait. The softness works to good effect.</td>', 'Nice high key portrait. The softness works to good effect.', '2008-05-16 22:27:14.000000', NULL, 1),
(4707591, 678507, 76335, '<td valign="top">Abstract and original. Beautiful shades of blue here. Great title.</td>', 'Abstract and original. Beautiful shades of blue here. Great title.', '2008-05-16 22:27:50.000000', NULL, 1),
(4707594, 678594, 76335, '<td valign="top">Needs more light, but I suppose that might keep him awake. Funny.</td>', 'Needs more light, but I suppose that might keep him awake. Funny.', '2008-05-16 22:28:30.000000', NULL, 1),
(4707596, 678648, 76335, '<td valign="top">Maybe it''s me, but this seems to have a slight red cast. Still, dramatic and beautiful.</td>', 'Maybe it''s me, but this seems to have a slight red cast. Still, dramatic and beautiful.', '2008-05-16 22:29:27.000000', NULL, 1),
(4707599, 678347, 76335, '<td valign="top">Nice subject and good exposure. Needs more contrast though.</td>', 'Nice subject and good exposure. Needs more contrast though.', '2008-05-16 22:30:01.000000', NULL, 1),
(4707601, 678354, 76335, '<td valign="top">Excellent smiles. One to frame for sure.</td>', 'Excellent smiles. One to frame for sure.', '2008-05-16 22:30:33.000000', NULL, 1),
(4707605, 678422, 76335, '<td valign="top">Not the best example of softness, but very original and nice high contrast tones.</td>', 'Not the best example of softness, but very original and nice high contrast tones.', '2008-05-16 22:30:59.000000', NULL, 1),
(4707608, 678588, 76335, '<td valign="top">Seems to have a slight red cast.</td>', 'Seems to have a slight red cast.', '2008-05-16 22:31:27.000000', NULL, 1),
