(4710775, 678560, 26559, '<td valign="top">I''m not sure whether the effect adds to this particular subject (spiky hair, guitar, leather jacket, soft focus...which one of these doesn''t belong) but I give you credit for actually executing on the soft focus challenge amidst so many just out-of-focus or DNMC entries.  Nice job.</td>', 'I''m not sure whether the effect adds to this particular subject (spiky hair, guitar, leather jacket, soft focus...which one of these doesn''t belong) but I give you credit for actually executing on the soft focus challenge amidst so many just out-of-focus or DNMC entries.  Nice job.', '2008-05-19 05:29:20.000000', NULL, 1),
(4710776, 678249, 26559, '<td valign="top">Nicely done, helps to draw attention to the yellow house.</td>', 'Nicely done, helps to draw attention to the yellow house.', '2008-05-19 05:30:22.000000', NULL, 1),
(4710777, 677167, 26559, '<td valign="top">Errrmmm...was this entered for the wrong challenge?  Does not seem to meet the Soft Focus challenge at all.</td>', 'Errrmmm...was this entered for the wrong challenge?  Does not seem to meet the Soft Focus challenge at all.', '2008-05-19 05:32:01.000000', NULL, 1),
